 s.painter.reset();s.painter.loaded=True;p0=path[0].copy();p0[2]=.055;s.painter.sample(p0,R);prev=path[0]
 for _ in range(5):s.painter.sample(prev,R)
 for pt in path[1:]:
  for k in range(1,6):s.painter.sample(prev+(pt-prev)*(k/5),R)
  prev=pt
