def shift(a,dr,dc):
 o=np.zeros_like(a);r0=max(0,-dr);r1=min(1024,1024-dr);c0=max(0,-dc);c1=min(1024,1024-dc);o[r0+dr:r1+dr,c0+dc:c1+dc]=a[r0:r1,c0:c1];return o
shifts=[(0,0)]*len(ms)
def union_all():
 u=np.zeros_like(mask)
 for m,(r,c) in zip(ms,shifts):u|=shift(m,r,c)
 return u
for it in range(4):
 for i in range(len(ms)):
  rest=np.zeros_like(mask)
  for j,m in enumerate(ms):
   if i!=j:rest|=shift(m,*shifts[j])
  best=(-1,None)
  for dr in range(-12,13):
   for dc in range(-12,13):
    u=rest|shift(ms[i],dr,dc);score=(u&mask).sum()/(u|mask).sum()
    if score>best[0]:best=(score,(dr,dc))
  shifts[i]=best[1]
 U=union_all(); print('iter',it,'shifts',shifts,'iou',(U&mask).sum()/(U|mask).sum(),'rec',(U&mask).sum()/mask.sum(),'area',U.sum(),flush=True)
np.save('/tmp/shifts.npy',np.array(shifts))
